package com.hmdp.ai.runtime.tool.skill;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.run.ExecutionContext;import com.hmdp.ai.port.*;import com.hmdp.ai.runtime.tool.*;import com.hmdp.ai.runtime.tool.skill.dto.*;import com.hmdp.dto.ai.ShopView;import org.springframework.stereotype.Component;import java.util.*;
@Component @AgentSkill(code="recommend-shops") public class RecommendShopsSkill extends ShopSkillSupport implements LocalSkill {public RecommendShopsSkill(ShopDataPort s,ReviewDataPort r,ObjectMapper m){super(s,r,m);}@Override public JsonNode execute(ExecutionContext c,JsonNode in){String pref=in.path("preference").asText("").trim(),cat=in.path("category").asText(null);if(pref.isEmpty())throw new IllegalArgumentException("preference is required");int limit=Math.max(1,Math.min(10,in.path("limit").asInt(5)));List<Scored> scored=new ArrayList<>();for(ShopView s:shops.findRecommendCandidates(cat,Math.max(20,limit*3))){double score=(s.getScore()==null?0:s.getScore())+Math.log10(Math.max(1,s.getSold()==null?0:s.getSold()))*5;String lower=pref.toLowerCase();String match="POPULARITY";if((s.getArea()!=null&&lower.contains(s.getArea().toLowerCase()))||(s.getName()!=null&&lower.contains(s.getName().toLowerCase()))){score+=20;match="TEXT_CONSTRAINT";}scored.add(new Scored(s,score,match));}scored.sort(Comparator.comparingDouble((Scored x)->x.score).reversed());List<ShopRecommendationItemData>items=new ArrayList<>();for(int i=0;i<Math.min(limit,scored.size());i++){Scored x=scored.get(i);items.add(new ShopRecommendationItemData(i+1,x.shop,Math.round(x.score*100.0)/100.0,x.match));}return json(new ShopRecommendationData(pref,cat,items));}private static final class Scored{final ShopView shop;final double score;final String match;Scored(ShopView s,double v,String m){shop=s;score=v;match=m;}}}
